{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Ensure all Cloud SQL database instance have backup configuration enabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The `backup_configuration` block explicitly sets `enabled = false`, which prevents automated backups and poses a significant risk of data loss."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Ensure all Cloud SQL database instance requires all incoming connections to use SSL",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The `ip_configuration` block sets `require_ssl = false`, allowing unencrypted connections to the database, which exposes data in transit to interception."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The database flag `log_lock_waits` is explicitly set to `off`, disabling logging of lock waits which hinders troubleshooting and security auditing of database contention."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = false\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n  }\n}",
  "fix_summary": "Enabled automated backups by setting `backup_configuration.enabled` to true. Enforced SSL for all incoming connections by setting `ip_configuration.require_ssl` to true. Enabled lock wait logging by changing the `log_lock_waits` database flag value from 'off' to 'on'."
}
